// Hydel (hydro-electric) power station showpiece, hand-made. Units: cm, about real size. A river valley runs along Z: the
// reservoir behind the dam (−Z), the powerhouse at the dam's foot (+Z, left bank), the river going on downstream. The dam
// crosses the valley along X. Outdoors: a sky and a 24-hour day. Helpers for later parts live on W.store.
const S = W.store;
S.matte = (c, r = 0.92) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: 0 });
S.concrete = S.matte('#c2bcb0', 0.88);
S.lamps = [];
S.lamp = (c = '#ffe2a8', k = 2.4) => { const m = W.glow(c, 0); S.lamps.push({ m, k }); return m; };
S.LAKE = 5600; S.CREST = 6200;
S.wAt = (z) => (z > 1500 ? 5000 + Math.min(1, (z - 1500) / 4000) * 5000 : z < -3000 ? 5000 + Math.min(1, (-z - 3000) / 6000) * 7000 : 5000);
S.h = (x, z) => { // the valley: flat between its sides, the hills rising beyond (the lake's bed lies under the water)
  const d = Math.abs(x) - S.wAt(z);
  if (d <= 0) return z < -1500 ? -400 : 0;
  const n = Math.sin(x * 0.0007 + z * 0.0003) * 320 + Math.sin(z * 0.0011 - x * 0.0004) * 260;
  return Math.min(9800, d * 1.35 + n * Math.min(1, d / 2500)) + (z < -1500 ? -400 * Math.max(0, 1 - d / 2000) : 0);
};
W.day({ start: 12, ground: '#6f7f4c' });
const land = W.group();
const g = new THREE.PlaneGeometry(46000, 42000, 96, 88);
g.rotateX(-Math.PI / 2);
g.translate(0, 0, -3000);
const pos = g.attributes.position, col = [];
const cLow = new THREE.Color('#6f8a4f'), cMid = new THREE.Color('#7c7a52'), cRock = new THREE.Color('#8b7f6e'), cBed = new THREE.Color('#5d5848'), c = new THREE.Color();
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), z = pos.getZ(i), y = S.h(x, z);
  pos.setY(i, y);
  const k = Math.min(1, Math.max(0, y / 7000));
  if (y < 0) c.copy(cBed); else c.copy(cLow).lerp(cMid, Math.min(1, k * 2)).lerp(cRock, Math.max(0, k * 1.6 - 0.6));
  col.push(c.r, c.g, c.b);
}
g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
g.computeVertexNormals();
land.add(new THREE.Mesh(g, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.96, metalness: 0 })));
const trees = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), S.matte('#3f6b35', 0.95), 120);
{
  const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3();
  let n = 0;
  for (let i = 0; i < 400 && n < 120; i++) {
    const x = ((i * 0.618034) % 1) * 40000 - 20000, z = ((i * 0.381966 + 0.13) % 1) * 36000 - 20000, y = S.h(x, z);
    if (y < 300 || y > 7500 || (z < -1500 && y < S.LAKE + 200)) continue;
    const s = 300 + (i % 5) * 70;
    M.compose(P.set(x, y + s * 0.8, z), Q, Z.set(s, s * 1.2, s));
    trees.setMatrixAt(n++, M);
  }
  trees.count = n;
}
land.add(trees);
W.add(land, { label: 'కొండలు', ground: true });
const lake = W.group();
const water = new THREE.MeshStandardMaterial({ color: '#2d6d93', roughness: 0.1, metalness: 0.15 });
lake.add(W.mesh(new THREE.PlaneGeometry(46000, 22500), water, { at: [0, S.LAKE, -12740], rot: [-90, 0, 0] }));
W.add(lake, { label: 'జలాశయం', heat: [24, 26], ground: true });
const river = W.group();
const rw = new THREE.MeshStandardMaterial({ color: '#3a7c9e', roughness: 0.18, metalness: 0.1 });
river.add(W.mesh(new THREE.PlaneGeometry(7600, 15500), rw, { at: [2800, 110, 10750], rot: [-90, 0, 0] }));
river.add(W.mesh(new THREE.PlaneGeometry(4200, 2900), rw, { at: [-3700, 100, 6750], rot: [-90, 0, 0] }));
W.add(river, { label: 'నది', heat: [24, 26], ground: true });

const S = W.store;
// a concrete gravity dam, 66 m from its foundation: its own weight holds the lake back. In the middle the spillway: a lower
// crest with four radial gates between piers and a bridge over them; at its foot a ski-jump throws flood water clear.
const across = (outline, x0, x1, mat) => { // a (z, y) cross-section stretched from x0 to x1
  const geo = W.extrude(outline, x1 - x0);
  geo.rotateY(-Math.PI / 2);
  return W.mesh(geo, mat, { at: [(x0 + x1) / 2, 0, 0] });
};
const body = [[-1500, -400], [-1500, S.CREST], [-700, S.CREST], [-700, 6000], [3000, 0], [3000, -400]];
const dam = W.group();
dam.add(across(body, -9600, 0, S.concrete), across(body, 4500, 9600, S.concrete));
dam.add(W.mesh(W.box(9600, 110, 40), S.matte('#d8d2c6'), { at: [-4800, S.CREST + 55, -1480] }), W.mesh(W.box(9600, 110, 40), S.matte('#d8d2c6'), { at: [-4800, S.CREST + 55, -720] }));
dam.add(W.mesh(W.box(5100, 110, 40), S.matte('#d8d2c6'), { at: [7050, S.CREST + 55, -1480] }), W.mesh(W.box(5100, 110, 40), S.matte('#d8d2c6'), { at: [7050, S.CREST + 55, -720] }));
const pole = W.metal('#8d939a', { rough: 0.5 }), head = S.lamp('#ffe7b0', 3);
for (let x = -9000; x <= 9000; x += 2000) {
  dam.add(W.mesh(W.cyl(8, 10, 600, 8), pole, { at: [x, S.CREST + 300, -760] }));
  dam.add(W.mesh(W.box(60, 10, 30), head, { at: [x, S.CREST + 595, -800] }));
}
dam.add(W.text('JARVIS జల విద్యుత్ కేంద్రం · 240 MW', { size: 150, at: [7050, 3800, 690], rot: [-31.7, 0, 0], color: '#f4f1ea', bg: '#2f5f8a' }));
W.add(dam, { label: 'డ్యామ్', heat: [24, 30] });
const ogee = [[-1500, -400], [-1500, 5450], [-1300, 5600], [-900, 5580], [-500, 5400], [0, 5000], [2600, 900], [3000, 520], [3400, 720], [3500, 720], [3500, -400]];
const spill = W.group();
spill.add(across(ogee, 0, 4500, S.concrete));
for (let i = 0; i <= 4; i++) { // the piers between the gates, and the bridge on them
  const x = i * 1125;
  spill.add(W.mesh(W.box(i === 0 || i === 4 ? 300 : 220, 1400, 1100), S.concrete, { at: [Math.min(4350, Math.max(150, x)), 5550, -1000] }));
}
spill.add(W.mesh(W.box(4500, 120, 800), S.concrete, { at: [2250, S.CREST + 60, -1100] }));
for (const z of [-1480, -720]) spill.add(W.mesh(W.box(4500, 110, 40), S.matte('#d8d2c6'), { at: [2250, S.CREST + 175, z] }));
spill.add(W.mesh(W.box(4500, 200, 900), S.concrete, { at: [2250, 900, 3950] })); // the apron below
W.add(spill, { label: 'స్పిల్‌వే', heat: [24, 30] });
const gates = W.group();
S.gates = [];
const gateM = W.paint('#3d6f9e', { metallic: 0.4, rough: 0.45 });
for (let i = 0; i < 4; i++) {
  const cx = 1125 * i + 562;
  const pivot = W.group({ at: [cx, 6000, -100] }); // (a radial gate: a curved plate on two arms; it turns up about its pins downstream)
  const plate = new THREE.Mesh(new THREE.CylinderGeometry(1080, 1080, 860, 24, 1, true, Math.PI * 0.94, Math.PI * 0.18), gateM);
  plate.rotation.z = Math.PI / 2;
  pivot.add(plate);
  for (const dx of [-400, 400]) pivot.add(W.mesh(W.box(40, 60, 1050), gateM, { at: [dx, -50, -525] }));
  gates.add(pivot);
  S.gates.push(pivot);
  gates.add(W.mesh(W.box(300, 260, 300), W.paint('#e0b324'), { at: [cx, S.CREST + 250, -1100] })); // its hoist
}
W.add(gates, { label: 'స్పిల్‌వే గేట్లు' });
const intake = W.group();
for (const x of [-5000, -3700, -2400]) {
  intake.add(W.mesh(W.box(400, 300, 400), W.paint('#e0b324'), { at: [x, S.CREST + 200, -1100] }));
  intake.add(W.mesh(W.box(700, 900, 40), W.metal('#55606b', { rough: 0.6 }), { at: [x, 4500, -1530] }));
}
W.add(intake, { label: 'ఇన్‌టేక్ గేట్లు' });
// the flood water that pours down the spillway when its gates are open (only then)
const sheetTex = W.canvasTex(64, 256);
{ const c = sheetTex.ctx; for (let y = 0; y < 256; y++) { c.fillStyle = 'rgba(255,255,255,' + (0.45 + 0.5 * Math.abs(Math.sin(y * 0.21) * Math.sin(y * 0.05))) + ')'; c.fillRect(0, y, 64, 1); } sheetTex.update(); sheetTex.texture.wrapS = sheetTex.texture.wrapT = THREE.RepeatWrapping; sheetTex.texture.repeat.set(6, 3); }
const flood = W.group();
const sheetM = new THREE.MeshStandardMaterial({ color: '#e6f4fb', emissive: '#6f8fa0', emissiveIntensity: 0.25, transparent: true, opacity: 0, depthWrite: false, roughness: 0.3 });
const fl = ogee.slice(2, 9).map(([z, y]) => [z, y + 70]);
const fGeo = W.extrude(fl.concat(fl.slice().reverse().map(([z, y]) => [z, y - 40])), 4300);
fGeo.rotateY(-Math.PI / 2);
const fsheet = W.mesh(fGeo, sheetM, { at: [2250, 0, 0] });
fsheet.userData.isEdge = true; fsheet.castShadow = false; fsheet.raycast = () => {};
flood.add(fsheet);
S.flood = { m: sheetM, tex: sheetTex.texture };
spill.add(flood);

const S = W.store;
const pen = W.group();
const steel = W.paint('#5b6670', { metallic: 0.45, rough: 0.5 });
S.units = [-5000, -3700, -2400];
const face = (z) => 6000 - (z + 700) * 6000 / 3700;
for (const x of S.units) {
  pen.add(W.mesh(W.tube([[x, 4700, -900], [x, face(-200) + 300, -200], [x, face(1500) + 300, 1500], [x, 900, 2900], [x, 500, 3500], [x, 320, 3800]], 230, 48), steel));
  for (const z of [400, 1400, 2400]) pen.add(W.mesh(W.box(700, Math.max(200, face(z) + 60), 260), S.concrete, { at: [x, Math.max(100, face(z) + 60) / 2, z] })); // its saddles
}
W.add(pen, { label: 'పెన్‌స్టాక్ పైపులు', heat: [22, 24] });

const S = W.store;
// the powerhouse at the dam's foot: below its floor three Francis turbines in their spiral casings; on the floor the round
// tops of three generators; a crane under the roof. Roof, walls and floor lift away (🧅).
const x0 = -5800, x1 = -1600, z0 = 3300, z1 = 5300, cx = (x0 + x1) / 2, cz = (z0 + z1) / 2;
const sub = W.group();
for (const [x, z, w, d] of [[cx, z0, x1 - x0, 60], [cx, z1, x1 - x0, 60], [x0, cz, 60, z1 - z0], [x1, cz, 60, z1 - z0]]) sub.add(W.mesh(W.box(w, 800, d), S.concrete, { at: [x, 400, z] }));
sub.add(W.mesh(W.box(x1 - x0, 40, z1 - z0), S.matte('#8f8a80'), { at: [cx, 20, cz] }));
const wallT = W.canvasTex(256, 128), glowT = W.canvasTex(256, 128);
{ const g = wallT.ctx, e = glowT.ctx; g.fillStyle = '#e6e1d6'; g.fillRect(0, 0, 256, 128); e.fillStyle = '#000'; e.fillRect(0, 0, 256, 128);
  for (let c = 0; c < 8; c++) { g.fillStyle = '#35506a'; g.fillRect(c * 32 + 6, 22, 20, 70); e.fillStyle = '#ffd9a0'; e.fillRect(c * 32 + 6, 22, 20, 70); }
  wallT.update(); glowT.update(); }
const wm = new THREE.MeshStandardMaterial({ map: wallT.texture, emissiveMap: glowT.texture, emissive: new THREE.Color('#ffc977'), emissiveIntensity: 0, roughness: 0.7 });
S.lamps.push({ m: wm, k: 0.9 });
const walls = W.group();
for (const [x, z, w, d] of [[cx, z0, x1 - x0, 40], [cx, z1, x1 - x0, 40], [x0, cz, 40, z1 - z0], [x1, cz, 40, z1 - z0]]) walls.add(W.mesh(W.box(w, 1800, d), wm, { at: [x, 1700, z] }));
W.add(walls, { label: 'పవర్‌హౌస్', layer: 1, peelBy: [0, 2400, 0], explode: [0, 0, 3000] });
walls.traverse((x) => { if (x.isMesh) x.castShadow = false; });
W.add(sub, { label: 'పవర్‌హౌస్ పునాది', layer: 4 });
const roof = W.group();
roof.add(W.mesh(W.box(x1 - x0 + 160, 60, z1 - z0 + 160), W.paint('#8b97a3', { metallic: 0.3, rough: 0.55 }), { at: [cx, 2630, cz] }));
const lampsM = S.lamp('#fff3dc', 2.2);
S.lamps[S.lamps.length - 1].always = 0.35;
for (let x = x0 + 500; x < x1; x += 800) roof.add(W.mesh(W.box(150, 20, 70), lampsM, { at: [x, 2590, cz] }));
W.add(roof, { label: 'పవర్‌హౌస్ పైకప్పు', layer: 0, peelBy: [0, 4600, 0], explode: [0, 4600, 0] });
roof.traverse((x) => { if (x.isMesh) x.castShadow = false; });
const floor = W.group();
const fm = S.matte('#9a958a', 0.8);
floor.add(W.mesh(W.box(x1 - x0, 40, 650), fm, { at: [cx, 780, z0 + 325] }), W.mesh(W.box(x1 - x0, 40, 650), fm, { at: [cx, 780, z1 - 325] }));
for (const x of [x0 + 300, -4350, -3050, x1 - 300]) floor.add(W.mesh(W.box(x === x0 + 300 || x === x1 - 300 ? 600 : 260, 40, 700), fm, { at: [x, 780, cz] }));
for (const z of [z0 + 650, z1 - 650]) floor.add(W.mesh(W.box(x1 - x0, 90, 20), W.paint('#e0b324'), { at: [cx, 845, z] }));
W.add(floor, { label: 'జనరేటర్ ఫ్లోర్', layer: 2, peelBy: [0, 1800, 0] });
const crane = W.group();
const cy = W.paint('#e0b324', { metallic: 0.3, rough: 0.45 });
for (const z of [z0 + 40, z1 - 40]) crane.add(W.mesh(W.box(x1 - x0, 50, 50), W.metal('#7d838b'), { at: [cx, 2200, z] }));
for (const dz of [-100, 100]) crane.add(W.mesh(W.box(120, 160, z1 - z0 - 80), cy, { at: [-2600 + dz, 2310, cz] }));
crane.add(W.mesh(W.box(380, 180, 380), cy, { at: [-2600, 2440, cz] }));
W.add(crane, { label: 'పవర్‌హౌస్ క్రేన్', layer: 2, peelBy: [0, 2000, 0] });
const hl = new THREE.PointLight(0xfff0d8, 1.8, 5000, 0);
hl.position.set(cx, 2300, cz);
sub.add(hl);

const S = W.store;
// each unit: water from its penstock goes round a spiral casing, through the wicket gates onto the Francis runner (inside),
// down the draft tube to the tailrace; one vertical shaft turns the generator above (187.5 a minute: 32 poles → 50 Hz)
const cz = 4300;
const turb = W.group(), gens = W.group();
const scroll = W.paint('#56626e', { metallic: 0.45, rough: 0.45 });
S.spiders = [];
for (const x of S.units) {
  const sp = new THREE.Mesh(new THREE.TorusGeometry(620, 230, 16, 40, Math.PI * 1.75), scroll);
  sp.rotation.x = Math.PI / 2; sp.position.set(x, 320, cz);
  turb.add(sp);
  turb.add(W.mesh(W.cyl(380, 380, 260, 32), W.metal('#8a9097', { rough: 0.35 }), { at: [x, 320, cz] }));
  turb.add(W.mesh(W.tube([[x, 200, cz], [x, 40, cz + 300], [x, 20, cz + 900], [x, 30, cz + 1500]], 300, 32), scroll)); // the draft tube
  turb.add(W.mesh(W.cyl(70, 70, 520, 16), W.metal('#c9cdd2'), { at: [x, 640, cz] }));
  const g = W.group({ at: [x, 0, cz] });
  g.add(W.mesh(W.cyl(520, 520, 620, 48), W.paint('#3f7b74', { metallic: 0.35, rough: 0.4 }), { at: [0, 1110, 0] }));
  g.add(W.mesh(W.cyl(540, 540, 60, 48), W.paint('#e0b324'), { at: [0, 1450, 0] }));
  const spider = W.group({ at: [0, 1500, 0] });
  spider.add(W.mesh(W.cyl(120, 120, 60, 24), W.metal('#c9cdd2')));
  for (let k = 0; k < 6; k++) spider.add(W.mesh(W.box(420, 40, 60), W.paint('#2f5f5a'), { at: [Math.cos(k * Math.PI / 3) * 210, 0, Math.sin(k * Math.PI / 3) * 210], rot: [0, -k * 60, 0] }));
  g.add(spider);
  S.spiders.push(spider);
  g.add(W.mesh(W.cyl(140, 160, 260, 24), W.paint('#3f6e8f'), { at: [0, 1660, 0] })); // the exciter
  gens.add(g);
}
W.add(turb, { label: 'ఫ్రాన్సిస్ టర్బైన్లు', heat: [22, 28], layer: 3 });
W.add(gens, { label: 'జనరేటర్లు', heat: [30, 70], layer: 3 });

const S = W.store;
const tr = W.group();
const tank = W.paint('#5f6b5e', { metallic: 0.35, rough: 0.55 });
for (const z of [3700, 4300, 4900]) {
  tr.add(W.mesh(W.box(500, 420, 380), tank, { at: [-6400, 260, z] }));
  for (let k = 0; k < 3; k++) tr.add(W.mesh(W.cyl(16, 22, 220, 10), S.matte('#7a4a32', 0.4), { at: [-6520 + k * 120, 580, z] }));
  tr.add(W.mesh(W.box(40, 360, 300), tank, { at: [-6680, 240, z] }));
}
W.add(tr, { label: 'ట్రాన్స్‌ఫార్మర్లు', heat: [30, 72] });
const sw = W.group();
const gal = W.metal('#aab2ba', { rough: 0.45 });
sw.add(W.mesh(W.box(2600, 10, 2400), S.matte('#8b867d', 0.98), { at: [-8200, 6, 7500] }));
for (const x of [-9200, -7200]) { for (const z of [6600, 8400]) sw.add(W.mesh(W.box(50, 1600, 50), gal, { at: [x, 800, z] })); sw.add(W.mesh(W.box(50, 50, 1850), gal, { at: [x, 1600, 7500] })); }
for (const z of [7100, 7500, 7900]) {
  sw.add(W.mesh(W.cyl(24, 24, 240, 10), S.matte('#9aa1a8', 0.5), { at: [-8200, 380, z] }));
  sw.add(W.mesh(W.box(24, 260, 24), gal, { at: [-8200, 130, z] }));
  sw.add(W.mesh(W.tube([[-6400, 700, 4300 + (z - 7500)], [-6900, 1300, 6000 + (z - 7500) * 0.5], [-7200, 1580, z]], 6, 16), W.metal('#c9a24a')));
}
W.add(sw, { label: 'స్విచ్‌యార్డ్', heat: [26, 40] });
const lines = W.group();
const tower = (x, z) => {
  const y = S.h(x, z), t = W.group({ at: [x, y, z] });
  for (const [dx, dz] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
    const A = new THREE.Vector3(dx * 230, 0, dz * 230), B = new THREE.Vector3(dx * 50, 2800, dz * 50);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(12, 12, A.distanceTo(B), 4), gal);
    m.position.copy(A).add(B).multiplyScalar(0.5); m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize());
    t.add(m);
  }
  t.add(W.mesh(W.box(40, 40, 1400), gal, { at: [0, 2450, 0] }), W.mesh(W.cone(60, 400, 4), gal, { at: [0, 3000, 0] }));
  return { t, top: [x, y + 2450, z] };
};
const T1 = tower(-11800, 8200), T2 = tower(-15800, 9800);
lines.add(T1.t, T2.t);
for (const dz of [-600, 0, 600]) {
  lines.add(W.mesh(W.tube([[-9200, 1580, 7500 + dz * 0.7], [-10500, (1580 + T1.top[1]) / 2 - 300, 7900 + dz], [T1.top[0], T1.top[1], T1.top[2] + dz]], 7, 20), W.metal('#6c7076')));
  lines.add(W.mesh(W.tube([[T1.top[0], T1.top[1], T1.top[2] + dz], [-13800, (T1.top[1] + T2.top[1]) / 2 - 400, 9000 + dz], [T2.top[0], T2.top[1], T2.top[2] + dz]], 7, 20), W.metal('#6c7076')));
}
W.add(lines, { label: 'ట్రాన్స్‌మిషన్ లైన్లు', heat: [26, 50] });

const S = W.store;
// running: the power bar opens the wicket gates; water spins the runners (hydel starts in minutes, not hours);
// 🚩 "spill": the four radial gates lift and flood water pours down the spillway
const cr = W.group();
cr.add(W.mesh(W.box(1200, 500, 1000), S.matte('#e4e1d9', 0.8), { at: [-800, 250, 4300] }));
cr.add(W.mesh(W.box(1200, 120, 30), S.lamp('#bfe6ff', 1.2), { at: [-800, 330, 4815] }));
S.lamps[S.lamps.length - 1].always = 0.6;
cr.add(W.mesh(W.box(1260, 40, 1060), W.paint('#9aa3ab'), { at: [-800, 520, 4300] }));
W.add(cr, { label: 'కంట్రోల్ రూమ్', heat: [24, 26] });
W.throttle({ label: 'గేట్', rise: 0.35, fall: 0.3, sound: 'water' });
W.sound({ kind: 'hum', label: 'జనరేటర్లు', gain: 0.55, f0: 100 });
W.sound({ kind: 'plant', label: 'ఫ్రాన్సిస్ టర్బైన్లు', gain: 0.5 });
const spillVoice = W.sound({ kind: 'water', label: 'స్పిల్‌వే గేట్లు', gain: 1.3 });
const foamGeo = new THREE.SphereGeometry(1, 10, 8), foam = [];
for (let i = 0; i < 16; i++) {
